import type { Difference, Formality, Language, Nuance } from "@kotori/domain"
import {
  bytea,
  doublePrecision,
  foreignKey,
  index,
  integer,
  jsonb,
  pgEnum,
  primaryKey,
  text,
  unique
} from "drizzle-orm/pg-core"
import { createdAt, table, timestamptz } from "./columns.ts"
import { entries, senses } from "./dictionary.ts"

// Everything here is generated by AI providers (Jev, Claude, ElevenLabs) for dictionary
// entries, keyed by entry and sense. It cascades from the dictionary and is rebuildable.

export const language = pgEnum("language", ["en", "ja"])
export const formality = pgEnum("formality", ["vulgar", "casual", "neutral", "polite", "formal"])
export const difference = pgEnum("difference", [
  "more_casual",
  "more_formal",
  "more_literary",
  "more_colloquial",
  "respectful",
  "humble",
  "more_specific",
  "more_general",
  "different_feeling",
  "different_usage"
])

/** Jev's nuance judgments per sense. */
export const senseNuance = table(
  "sense_nuance",
  {
    entryId: integer().notNull(),
    sense: integer().notNull(),
    nuance: jsonb().$type<Nuance>().notNull(),
    /** The raw answer distributions, so thresholds and labels can be re-derived without paying for inference again. */
    answers: jsonb().notNull(),
    model: text().notNull(),
    createdAt: createdAt()
  },
  (t) => [
    primaryKey({ columns: [t.entryId, t.sense] }),
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete("cascade")
  ]
)

export const similarWords = table(
  "similar_words",
  {
    entryId: integer().notNull(),
    sense: integer().notNull(),
    similarId: integer()
      .notNull()
      .references(() => entries.id, { onDelete: "cascade" }),
    similarity: doublePrecision().notNull(),
    difference: difference().$type<Difference>().notNull(),
    confidence: doublePrecision().notNull()
  },
  (t) => [
    primaryKey({ columns: [t.entryId, t.sense, t.similarId] }),
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete("cascade")
  ]
)

export const examples = table(
  "examples",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    entryId: integer().notNull(),
    sense: integer().notNull(),
    position: integer().notNull(),
    ja: text().notNull(),
    /** The Japanese sentence with `{base|reading}` furigana. */
    furigana: text().notNull(),
    en: text().notNull(),
    formality: formality().$type<Formality>().notNull(),
    note: text(),
    model: text().notNull(),
    createdAt: createdAt()
  },
  (t) => [
    foreignKey({ columns: [t.entryId, t.sense], foreignColumns: [senses.entryId, senses.position] }).onDelete(
      "cascade"
    ),
    index("examples_sense").on(t.entryId, t.sense, t.position)
  ]
)

/**
 * Content-addressed speech clips: `key` is sha256(voice, model, text), so the same
 * phrase is never synthesised twice. Metadata here, bytes in `audio_files`.
 */
export const audio = table("audio", {
  key: text().primaryKey(),
  text: text().notNull(),
  language: language().$type<Language>().notNull(),
  voiceId: text().notNull(),
  modelId: text().notNull(),
  /** Characters billed by the provider, for the monthly budget. */
  characters: integer().notNull(),
  bytes: integer().notNull(),
  createdAt: createdAt()
})

/** The clip bytes, in the database so the API and the worker share them without a disk. */
export const audioFiles = table("audio_files", {
  key: text()
    .primaryKey()
    .references(() => audio.key, { onDelete: "cascade" }),
  data: bytea().notNull()
})

/** The pronunciation of an entry's headword. */
export const entryAudio = table("entry_audio", {
  entryId: integer()
    .primaryKey()
    .references(() => entries.id, { onDelete: "cascade" }),
  audioKey: text()
    .notNull()
    .references(() => audio.key)
})

/** An example sentence spoken, in Japanese and optionally in English. */
export const exampleAudio = table(
  "example_audio",
  {
    exampleId: integer()
      .notNull()
      .references(() => examples.id, { onDelete: "cascade" }),
    language: language().$type<Language>().notNull(),
    audioKey: text()
      .notNull()
      .references(() => audio.key)
  },
  (t) => [primaryKey({ columns: [t.exampleId, t.language] })]
)

export const jobKind = pgEnum("job_kind", ["nuance", "examples", "audio"])
export const jobStatus = pgEnum("job_status", ["queued", "running", "done", "failed"])

/** Enrichment work queue, shared by the API (on-demand requests) and the worker. One job per kind and entry. */
export const jobs = table(
  "jobs",
  {
    id: integer().primaryKey().generatedAlwaysAsIdentity(),
    kind: jobKind().notNull(),
    entryId: integer()
      .notNull()
      .references(() => entries.id, { onDelete: "cascade" }),
    priority: integer().notNull().default(0),
    status: jobStatus().notNull().default("queued"),
    attempts: integer().notNull().default(0),
    error: text(),
    /** Not before this moment; pushed into the future by retries. */
    runAfter: timestamptz().notNull().defaultNow(),
    createdAt: createdAt(),
    updatedAt: timestamptz().notNull().defaultNow()
  },
  (t) => [
    unique("jobs_kind_entry").on(t.kind, t.entryId),
    index("jobs_pending").on(t.status, t.priority.desc(), t.runAfter)
  ]
)
